import math
# pure python Gauss-Newton with manual linear solve (6 unknowns)
def residual(vals):
    R=vals[0]; r=vals[1]; angs=vals[2:6]
    Cb=(0.0,1-R); rr=1-r
    ps=[(rr*math.cos(a),rr*math.sin(a)) for a in angs]
    def d(p,q): return math.hypot(p[0]-q[0],p[1]-q[1])
    res=[]
    for p in ps: res.append(d(p,Cb)-(R+r))
    for i in range(3): res.append(d(ps[i],ps[i+1])-2*r)
    return res

def solve_linear(A,b):
    n=len(A); M=[row[:]+[b[i]] for i,row in enumerate(A)]
    for c in range(n):
        piv=max(range(c,n),key=lambda r:abs(M[r][c]))
        M[c],M[piv]=M[piv],M[c]
        if abs(M[c][c])<1e-14: return None
        for r in range(n):
            if r!=c:
                f=M[r][c]/M[c][c]
                for k in range(c,n+1): M[r][k]-=f*M[c][k]
    return [M[i][n]/M[i][i] for i in range(n)]

def solve(vals):
    for _ in range(300):
        r0=residual(vals)
        n=len(vals)
        J=[[0.0]*n for _ in range(len(r0))]
        for k in range(n):
            dv=vals[:]; h=1e-6; dv[k]+=h
            rr=residual(dv)
            for i in range(len(r0)): J[i][k]=(rr[i]-r0[i])/h
        # normal equations J^T J step = -J^T r0
        A=[[sum(J[i][a]*J[i][b] for i in range(len(r0))) for b in range(n)] for a in range(n)]
        b=[-sum(J[i][a]*r0[i] for i in range(len(r0))) for a in range(n)]
        for a in range(n): A[a][a]+=1e-9
        step=solve_linear(A,b)
        if step is None: break
        vals=[vals[i]+0.5*step[i] for i in range(n)]
    return vals, math.sqrt(sum(x*x for x in residual(vals)))

