def F(R,r,c,d):
    a=R; b=math.sqrt((1-R)**2-R**2)
    return [R**2+b**2-(1-R)**2,
            c*c+d*d-(1-r)**2,
            c*c+(d+(1-r))**2-(2*r)**2,
            (c-a)**2+(d-b)**2-(R+r)**2]
def solve(x0):
    x=list(x0)
    for it in range(300):
        f=F(*x)
        J=[[0.0]*4 for _ in range(4)]
        h=1e-7
        for j in range(4):
            xp=x[:]; xp[j]+=h
            fp=F(*xp)
            for i in range(4): J[i][j]=(fp[i]-f[i])/h
        A=[J[i][:]+[-f[i]] for i in range(4)]
        ok=True
        for col in range(4):
            p=max(range(col,4),key=lambda rr:abs(A[rr][col]))
            if abs(A[p][col])<1e-14: ok=False;break
            A[col],A[p]=A[p],A[col]
            for rr in range(4):
                if rr!=col:
                    fac=A[rr][col]/A[col][col]
                    for cc in range(col,5): A[rr][cc]-=fac*A[col][cc]
        if not ok: return None
        dx=[A[i][4]/A[i][i] for i in range(4)]
        for i in range(4): x[i]+=dx[i]
        if max(abs(v) for v in dx)<1e-13: break
    return x
