import numpy as np, math

def build(ts, rs):
    return np.array([[ (1-rs[i])*math.cos(ts[i]), (1-rs[i])*math.sin(ts[i])] for i in range(len(rs))])

def pen(x):
    ts=x[:5]; rs=x[5:]
    C=build(ts,rs); p=0
    for i in range(4):
        d=np.linalg.norm(C[i]-C[i+1])-(rs[i]+rs[i+1]); p+=d*d
    d=np.linalg.norm(C[4]-C[0])-(rs[4]+rs[0]); p+=d*d
    return p

def obj(x):
    return -np.sum(x[5:]) + 1000*pen(x)

# simple Nelder-Mead implementation
def nelder_mead(f, x0, steps=0.05, maxiter=40000):
    n=len(x0)
    simp=[np.array(x0,float)]
    for i in range(n):
        p=np.array(x0,float); p[i]+=steps; simp.append(p)
    simp=np.array(simp)
    fv=np.array([f(s) for s in simp])
    for it in range(maxiter):
        idx=np.argsort(fv); simp=simp[idx]; fv=fv[idx]
        cen=simp[:-1].mean(axis=0)
        xr=cen+(cen-simp[-1]); fr=f(xr)
        if fr<fv[0]:
            xe=cen+2*(cen-simp[-1]); fe=f(xe)
            if fe<fr: simp[-1]=xe; fv[-1]=fe
            else: simp[-1]=xr; fv[-1]=fr
        elif fr<fv[-2]:
            simp[-1]=xr; fv[-1]=fr
        else:
            xc=cen+0.5*(simp[-1]-cen); fc=f(xc)
            if fc<fv[-1]: simp[-1]=xc; fv[-1]=fc
            else:
                for i in range(1,n+1):
                    simp[i]=simp[0]+0.5*(simp[i]-simp[0]); fv[i]=f(simp[i])
    idx=np.argsort(fv)
    return simp[idx[0]], fv[idx[0]]

