    for i in range(5):
        for j in range(i+1,5):
            d=math.dist(C[i],C[j])-(sizes[i]+sizes[j])
            if d<0: p+=-d
    return p

def descend(angles, sizes, iters=2000):
    angles=list(angles); sizes=list(sizes)
    cur=sum(sizes)
    for it in range(iters):
        # try growing the smallest disc
        C=centres(angles,sizes)
        # push all pairs to be tangent (grow) then fix overlaps
        for i in range(5):
            # estimate max growth of disc i keeping non-overlap
            maxg=1.0-sizes[i]
            for j in range(5):
                if j==i: continue
                d=math.dist(C[i],C[j])-sizes[i]-sizes[j]
                maxg=min(maxg, d)  # can grow by this much (approx, ignoring centre shift)
            if maxg>0:
                sizes[i]+=maxg*0.5
        # remove overlaps
        for k in range(200):
            p=overlap_pen(angles,sizes)
            if p<1e-9: break
            C=centres(angles,sizes)
            for i in range(5):
                for j in range(i+1,5):
                    d=math.dist(C[i],C[j])-(sizes[i]+sizes[j])
                    if d<0:
                        sizes[i]=max(0.05,sizes[i]+d*0.3)
                        sizes[j]=max(0.05,sizes[j]+d*0.3)
        # also wiggle angles
        for i in range(5):
            a2=angles[i]+random.gauss(0,0.03)
            s2=sizes[i]
            old=angles[i]; angles[i]=a2
            if overlap_pen(angles,sizes)>overlap_pen([old]*1+angles[1:],sizes):
                pass
            angles[i]=a2  # keep
        # fix overlaps again
        for k in range(100):
            p=overlap_pen(angles,sizes)
            if p<1e-9: break
            C=centres(angles,sizes)
            for i in range(5):
                for j in range(i+1,5):
                    d=math.dist(C[i],C[j])-(sizes[i]+sizes[j])
                    if d<0:
                        sizes[i]=max(0.05,sizes[i]+d*0.3)
                        sizes[j]=max(0.05,sizes[j]+d*0.3)
    return angles, sizes

