import math
def rim_pos(a_deg, r):
    a = math.radians(a_deg)
    return ((1-r)*math.cos(a), (1-r)*math.sin(a))

# Try a large disc and 4 smaller, but leave a gap between last and first so no wrap overlap.
# March from large disc angle, going ccw, only 4 discs, last one not reaching back.
def build(sizes, start_deg, direction=1):
    angles=[start_deg]
    prev=start_deg
    for i in range(1,len(sizes)):
        r_prev=sizes[i-1]; r_cur=sizes[i]; d=r_prev+r_cur
        lo,hi=prev,prev+180*direction
        def dist(a):
            p=rim_pos(a,r_cur); q=rim_pos(prev,r_prev)
            return math.hypot(p[0]-q[0],p[1]-q[1])
        for _ in range(200):
            mid=(lo+hi)/2
            if (dist(mid)<d)==(direction>0): lo=mid
            else: hi=mid
        prev=(lo+hi)/2
        angles.append(prev)
    return angles

